--- a/services/compat/proxy/media_negotiation.go
+++ b/services/compat/proxy/media_negotiation.go
@@ -12,6 +12,22 @@
 func negotiate(r *http.Request) (string, error) {
+    // prefer explicit header
+    ct := r.Header.Get("Content-Type")
+    if ct != "" {
+        return normalize(ct), nil
+    }
+    // fallback to first-512-bytes sniff
+    buf := make([]byte, 512)
+    n, _ := io.ReadFull(r.Body, buf)
+    r.Body = io.NopCloser(io.MultiReader(bytes.NewReader(buf[:n]), r.Body))
+    if looksLikeJSON(buf[:n]) { return "application/json", nil }
+    return "application/octet-stream", nil
 }

